<span class="line"><span style="--shiki-light:#383A42;--shiki-dark:#D19A66;">VALID_NAMES_SET</span><span style="--shiki-light:#383A42;--shiki-dark:#56B6C2;"> =</span><span style="--shiki-light:#0184BC;--shiki-dark:#56B6C2;"> set</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;">(</span><span style="--shiki-light:#383A42;--shiki-dark:#D19A66;">VALID_NAMES</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;">)</span></span>
